use std::fs

trait Pricing {
    fn total(&self, qty: int, unit: int) -> int
}

struct Plain {}
struct Bulk {}
struct Member {}

impl Pricing for Plain {
    fn total(self, qty: int, unit: int) -> int {
        qty * unit
    }
}

impl Pricing for Bulk {
    fn total(self, qty: int, unit: int) -> int {
        let t = qty * unit
        if qty >= 10 { t - t * 10 / 100 } else { t }
    }
}

impl Pricing for Member {
    fn total(self, qty: int, unit: int) -> int {
        let t = qty * unit
        let mut r = t - t * 5 / 100
        if qty >= 3 { r -= 100 }
        if r < 0 { r = 0 }
        r
    }
}

fn price(kind: string, qty: int, unit: int) -> int {
    if kind == "plain" {
        let p = Plain {}
        p.total(qty, unit)
    } else if kind == "bulk" {
        let p = Bulk {}
        p.total(qty, unit)
    } else if kind == "member" {
        let p = Member {}
        p.total(qty, unit)
    } else {
        -1
    }
}

fn money(c: int) -> string {
    let d = c / 100
    let r = c % 100
    let sign = "$"
    if r < 10 { "${sign}${d}.0${r}" } else { "${sign}${d}.${r}" }
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut sum = 0
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() < 4 { continue }
        let qty: int = parts[1].parse::<int>().unwrap_or(0)
        let unit: int = parts[2].parse::<int>().unwrap_or(0)
        let c = price(parts[3], qty, unit)
        if c < 0 {
            println("${parts[0]} invalid kind")
        } else {
            sum += c
            println("${parts[0]} ${money(c)}")
        }
    }
    println("total ${money(sum)}")
}

